{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello आपको 3 feet tempered glass railing की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "जी जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "कितनी feet, square feet या meter चाहिए होगी आपको?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "Ma'am 3 feet में चाहिए।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "3 feet मतलब उसकी ऊंचाई चाहिए।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "पर आपको कुल कितनी quantity चाहिए जैसे कितने feet या square feet की जरूरत है?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "और"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "running मानिए आपकी आवाज़।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "Sorry आपकी आवाज़ clear नहीं आई ज़रा दोबारा।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "पर आप कुल कितनी quantity बता सकते हैं?"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "जैसे कितने feet या square feet चाहिए?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "कम से कम एक तो दो सौ square feet।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं आपको glass thickness 12 mm ही चाहिए ना?"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "जी जी।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "अब mounting system के बारे में बात कर लेते हैं।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "आपको spindle mounted चाहिए या post mounted?"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "इसको पता नहीं कौन से में कितने हैं।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "मैं आपको समझा देती हूं mounting system का मतलब है कि glass को कैसे fit किया जाएगा।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "आप इनमें से क्या पसंद करेंगे?"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "मेरे को दोनों नहीं पता है ना मतलब कौन सा क्या है।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "कोई बात नहीं, यह detail आप seller से discuss कर सकते हैं।"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "चलिए अब आपकी city confirm कर लेते हैं।"
    },
    {
      "i": 29,
      "speaker": "caller",
      "text": "जीसे आ रहा है।"
    }
  ]
}
